title:
// ❌ props로 초기화하려면 useEffect로 "동기화"해야 함
const useBearStore = create((set) => ({
  bears: 0,  // 기본값으로 먼저 생성
}))

const App = ({ initialBears }) => {
  useEffect(() => {
    useBearStore.set((prev) => ({ ...prev, bears: initialBears }))
  }, [initialBears])

  return <RestOfTheApp />
}

